p=argparse.ArgumentParser();p.add_argument('--asset',type=Path,required=True);p.add_argument('--tag',required=True);p.add_argument('--no-tetgen',action='store_true');a=p.parse_args();d=np.load(a.asset,allow_pickle=True);rawV=d['skin_vertices'].astype(float);rawF=d['skin_faces'];used=np.unique(rawF);mp=np.full(len(rawV),-1,int);mp[used]=np.arange(len(used));V=rawV[used];F=mp[rawF].astype(np.int32);fix=pymeshfix.PyTMesh();fix.set_quiet(True);fix.load_array(V,F);started=time.perf_counter();nb=fix.fill_small_boundaries(nbe=0,refine=True);VV,FF=fix.return_arrays();dist,source=cKDTree(VV).query(V);maxerr=float(max(dist));originalkeys={tuple(sorted(map(int,x))) for x in source[F]};newkeys={tuple(sorted(map(int,x))) for x in FF};missing=originalkeys-newkeys;tags=np.array([1 if tuple(sorted(map(int,x))) in originalkeys else 2 for x in FF],np.int32);stats=surface_stats(VV,FF);cg=check(VV,FF,tags);out={'input':str(a.asset),'input_sha256':sha(a.asset),'algorithm':'PyTMesh.fill_small_boundaries(nbe=0,refine=True) only; no global clean/repair','library_version':getattr(pymeshfix,'__version__','unknown'),'filled_boundary_count':int(nb),'max_original_skin_vertex_displacement_m':maxerr,'missing_original_skin_faces':len(missing),'original_skin_faces':len(F),'new_cap_faces':int(sum(tags==2)),'topology':stats,'cgal_intersections':cg,'wall_seconds':time.perf_counter()-started};np.savez_compressed(H/(a.tag+'_meshfix_plc.npz'),vertices=VV,faces=FF,face_markers=tags,source_skin_vertex_ids=used,source_skin_to_output_vertex=source);(H/(a.tag+'_meshfix_metrics.json')).write_text(json.dumps(out,indent=2));print(a.tag,'originalmaxerr',maxerr,'missingFaces',len(missing),'watertight',stats['watertight'],'nonmanifold',stats['nonmanifold_edges'],'CGAL',cg['cgal_intersecting_face_pairs'],flush=True)
